from decimal import Decimal

import pytest

from payment.domain.money import Money


def test_the_currency_is_normalised_to_upper_case() -> None:
    assert Money(Decimal("1"), "eur").currency == "EUR"


def test_the_smallest_positive_amount_is_accepted() -> None:
    assert Money(Decimal("0.01"), "EUR").amount == Decimal("0.01")


@pytest.mark.parametrize("amount", [Decimal("0"), Decimal("-1")])
def test_a_non_positive_amount_is_rejected(amount: Decimal) -> None:
    with pytest.raises(ValueError, match="positive"):
        Money(amount, "EUR")


@pytest.mark.parametrize("currency", ["", " ", "  \t"])
def test_a_blank_currency_is_rejected(currency: str) -> None:
    with pytest.raises(ValueError, match="currency is required"):
        Money(Decimal("1"), currency)


def test_an_amount_of_one_is_valid_with_a_non_blank_currency() -> None:
    assert Money(Decimal("1"), " x ").currency == " X "
EOF
cat >> tests/unit/test_authorize_payment.py <<'EOF'


def test_the_receipt_states_currency_amount_and_outcome() -> None:
    receipts = InMemoryReceiptStore()
    handler = AuthorizePayment(AlwaysAnswers(AuthorizationOutcome.DECLINED), receipts)

    handler.handle("ORD-3", Money(Decimal("42.50"), "eur"))

    assert receipts.saved == {"ORD-3": "EUR 42.50 -> DECLINED"}
EOF
